    "content": "\u10E1\u10D0\u10EC\u10DB\u10D4\u10DC\u10D3\u10D4\u10D1\u10D8\u10E1 \u10E0\u10D4\u10D6\u10D8\u10DC\u10D8\u10E1 \u10DE\u10D8\u10E0\u10D4\u10D1\u10D8 \u10D7\u10E3 \u10D6\u10DD\u10DA\u10D4\u10D1\u10E1 \u10E2\u10DD\u10D5\u10D4\u10D1\u10E1, \u10E8\u10D4\u10EA\u10D5\u10D0\u10DA\u10D4 \u2014 \u10EA\u10E3\u10D3\u10D8 \u10E1\u10D0\u10EC\u10DB\u10D4\u10DC\u10D3\u10D8 \u10EC\u10D5\u10D8\u10DB\u10D0\u10E8\u10D8 \u10EE\u10D8\u10DA\u10D5\u10D0\u10D3\u10DD\u10D1\u10D0\u10E1 \u10D0\u10DB\u10EA\u10D8\u10E0\u10D4\u10D1\u10E1.",
