    "category": "\u10D8\u10E1\u10E2\u10DD\u10E0\u10D8\u10D0",
    "content": "30/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1648 \u10EC\u10DA\u10D8\u10E1 30 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10DB\u10D8\u10E3\u10DC\u10E1\u10E2\u10D4\u10E0\u10D8\u10E1\u10D0 \u10D3\u10D0 \u10DD\u10E1\u10DC\u10D0\u10D1\u10E0\u10D8\u10E3\u10D9\u10D8\u10E1 \u10D6\u10D0\u10D5\u10D4\u10D1\u10DB\u10D0 \u10DC\u10D8\u10D3\u10D4\u10E0\u10DA\u10D0\u10DC\u10D3\u10D4\u10D1\u10E1\u10D0 \u10D3\u10D0 \u10D4\u10E1\u10DE\u10D0\u10DC\u10D4\u10D7\u10E1 \u10E8\u10DD\u10E0\u10D8\u10E1 \u10DD\u10DB\u10D8 \u10D3\u10D0\u10D0\u10E1\u10E0\u10E3\u10DA\u10D0.",
