    "category": "\u10EA\u10D8\u10E2\u10D0\u10E2\u10D0",
    "content": "\u201E\u10E8\u10D4\u10E1\u10D0\u10EB\u10DA\u10D4\u10D1\u10DA\u10DD\u10D1\u10D0 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E1\u10D0\u10DB\u10E3\u10E8\u10D0\u10DD \u10E2\u10D0\u10DC\u10E1\u10D0\u10EA\u10DB\u10D4\u10DA\u10E8\u10D8 \u10D2\u10D0\u10DB\u10DD\u10EC\u10E7\u10DD\u10D1\u10D8\u10DA\u10D8 \u10DB\u10DD\u10D3\u10D8\u10E1.\u201C \u2014 \u10D7\u10DD\u10DB\u10D0\u10E1 \u10D4\u10D3\u10D8\u10E1\u10DD\u10DC\u10D8",
