    "category": "\u10D8\u10E1\u10E2\u10DD\u10E0\u10D8\u10D0",
    "content": "23/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 393 \u10EC\u10DA\u10D8\u10E1 23 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10D7\u10D4\u10DD\u10D3\u10DD\u10E1\u10D8\u10E3\u10E1 I-\u10DB\u10D0 \u10D7\u10D0\u10D5\u10D8\u10E1\u10D8 \u10E0\u10D5\u10D0 \u10EC\u10DA\u10D8\u10E1 \u10D5\u10D0\u10DF\u10D8 \u10F0\u10DD\u10DC\u10DD\u10E0\u10D8\u10E3\u10E1\u10D8 \u10D7\u10D0\u10DC\u10D0\u10D8\u10DB\u10DE\u10D4\u10E0\u10D0\u10E2\u10DD\u10E0\u10D0\u10D3 \u10D2\u10D0\u10DB\u10DD\u10D0\u10EA\u10EE\u10D0\u10D3\u10D0.",
