    "content": "\u201E\u10E7\u10D5\u10D4\u10DA\u10D0\u10D6\u10D4 \u10E0\u10D7\u10E3\u10DA\u10D8 \u10D2\u10D0\u10DB\u10D0\u10E0\u10EF\u10D5\u10D4\u10D1\u10D0 \u10E1\u10D0\u10D9\u10E3\u10D7\u10D0\u10E0 \u10D7\u10D0\u10D5\u10D6\u10D4 \u10D2\u10D0\u10DB\u10D0\u10E0\u10EF\u10D5\u10D4\u10D1\u10D0\u10D0.\u201C \u2014 \u10D0\u10E0\u10D8\u10E1\u10E2\u10DD\u10E2\u10D4\u10DA\u10D4",
