    "content": "01/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1959 \u10EC\u10DA\u10D8\u10E1 1 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10E4\u10E3\u10DA\u10EE\u10D4\u10DC\u10E1\u10D8\u10DD \u10D1\u10D0\u10E2\u10D8\u10E1\u10E2\u10D0\u10DB \u10D9\u10E3\u10D1\u10D0 \u10D3\u10D0\u10E2\u10DD\u10D5\u10D0, \u10E0\u10D0\u10EA \u10D9\u10E3\u10D1\u10D8\u10E1 \u10E0\u10D4\u10D5\u10DD\u10DA\u10E3\u10EA\u10D8\u10D8\u10E1 \u10D2\u10D0\u10D3\u10D0\u10DB\u10EC\u10E7\u10D5\u10D4\u10E2 \u10D4\u10E2\u10D0\u10DE\u10D0\u10D3 \u10D8\u10E5\u10EA\u10D0.",
