    "content": "\u201E\u10E7\u10D5\u10D4\u10DA\u10D0\u10D6\u10D4 \u10DB\u10DC\u10D8\u10E8\u10D5\u10DC\u10D4\u10DA\u10DD\u10D5\u10D0\u10DC\u10D8 \u10D1\u10E0\u10EB\u10DD\u10DA\u10D4\u10D1\u10D8 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E3\u10EE\u10D8\u10DA\u10D0\u10D5\u10D8\u10D0.\u201C",
