    "content": "13/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1915 \u10EC\u10DA\u10D8\u10E1 13 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10D8\u10E2\u10D0\u10DA\u10D8\u10D8\u10E1 \u10D0\u10D5\u10D4\u10EA\u10D0\u10DC\u10DD\u10E1 \u10DB\u10D8\u10EC\u10D8\u10E1\u10EB\u10D5\u10E0\u10D0\u10DB \u10D3\u10D0\u10D0\u10EE\u10DA\u10DD\u10D4\u10D1\u10D8\u10D7 30 \u10D0\u10D7\u10D0\u10E1\u10D8 \u10D0\u10D3\u10D0\u10DB\u10D8\u10D0\u10DC\u10D8 \u10D8\u10DB\u10E1\u10EE\u10D5\u10D4\u10E0\u10DE\u10DA\u10D0.",
