    "content": "06/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1622 \u10EC\u10DA\u10D8\u10E1 6 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10E0\u10DD\u10DB\u10D8\u10E1 \u10DE\u10D0\u10DE\u10DB\u10D0 \u10D2\u10E0\u10D8\u10D2\u10DD\u10DA XV-\u10DB \u10E9\u10D0\u10DB\u10DD\u10D0\u10E7\u10D0\u10DA\u10D8\u10D1\u10D0 Propaganda Fide-\u10D8\u10E1 \u10D9\u10DD\u10DC\u10D2\u10E0\u10D4\u10D2\u10D0\u10EA\u10D8\u10D0, \u10E0\u10DD\u10DB\u10D4\u10DA\u10D8\u10EA \u10DB\u10DD\u10D2\u10D5\u10D8\u10D0\u10DC\u10D4\u10D1\u10D8\u10D7 \u10E1\u10D0\u10E5\u10D0\u10E0\u10D7\u10D5\u10D4\u10DA\u10DD\u10E8\u10D8 \u10D9\u10D0\u10D7\u10DD\u10DA\u10D8\u10D9\u10E3\u10E0 \u10DB\u10D8\u10E1\u10D8\u10D4\u10D1\u10D7\u10D0\u10DC\u10D0\u10EA \u10D8\u10E7\u10DD \u10D3\u10D0\u10D9\u10D0\u10D5\u10E8\u10D8\u10E0\u10D4\u10D1\u10E3\u10DA\u10D8.",
