    "category": "\u10D8\u10E1\u10E2\u10DD\u10E0\u10D8\u10D0",
    "content": "24/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1848 \u10EC\u10DA\u10D8\u10E1 24 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10EF\u10D4\u10D8\u10DB\u10E1 \u10DB\u10D0\u10E0\u10E8\u10D0\u10DA\u10DB\u10D0 \u10D9\u10D0\u10DA\u10D8\u10E4\u10DD\u10E0\u10DC\u10D8\u10D0\u10E8\u10D8 \u10E1\u10D0\u10E2\u10D4\u10E0\u10D8\u10E1 \u10EC\u10D8\u10E1\u10E5\u10D5\u10D8\u10DA\u10D7\u10D0\u10DC \u10DD\u10E5\u10E0\u10DD \u10D0\u10E6\u10DB\u10DD\u10D0\u10E9\u10D8\u10DC\u10D0, \u10E0\u10D0\u10DB\u10D0\u10EA \u10D9\u10D0\u10DA\u10D8\u10E4\u10DD\u10E0\u10DC\u10D8\u10D8\u10E1 \u10DD\u10E5\u10E0\u10DD\u10E1 \u10EA\u10D8\u10D4\u10D1-\u10EA\u10EE\u10D4\u10DA\u10D4\u10D1\u10D0 \u10D2\u10D0\u10DB\u10DD\u10D8\u10EC\u10D5\u10D8\u10D0.",
