    "content": "\u201E\u10D5\u10D8\u10DC\u10EA \u10D9\u10D8\u10D7\u10EE\u10D5\u10D0\u10E1 \u10E1\u10D5\u10D0\u10DB\u10E1, \u10EE\u10E3\u10D7\u10D8 \u10EC\u10E3\u10D7\u10D8\u10D7 \u10E1\u10E3\u10DA\u10D4\u10DA\u10D8\u10D0; \u10D5\u10D8\u10DC\u10EA \u10D0\u10E0 \u10E1\u10D5\u10D0\u10DB\u10E1, \u10DB\u10D7\u10D4\u10DA\u10D8 \u10EA\u10EE\u10DD\u10D5\u10E0\u10D4\u10D1\u10D0 \u10E1\u10E3\u10DA\u10D4\u10DA\u10D8 \u10E0\u10E9\u10D4\u10D1\u10D0.\u201C \u2014 \u10E9\u10D8\u10DC\u10E3\u10E0\u10D8 \u10D0\u10DC\u10D3\u10D0\u10D6\u10D0",
