    "content": "\u201E\u10E7\u10D5\u10D4\u10DA\u10D0\u10D6\u10D4 \u10D3\u10D8\u10D3\u10D8 \u10E8\u10D4\u10EA\u10D3\u10DD\u10DB\u10D0 \u10D0\u10E0\u10D8\u10E1 \u10E8\u10D4\u10EA\u10D3\u10DD\u10DB\u10D8\u10E1 \u10D3\u10D0\u10E8\u10D5\u10D4\u10D1\u10D8\u10E1 \u10E8\u10D8\u10E8\u10D8.\u201C",
