    "category": "\u10EA\u10D8\u10E2\u10D0\u10E2\u10D0",
    "content": "\u201E\u10D7\u10E3 \u10D2\u10D8\u10DC\u10D3\u10D0 \u10E1\u10EC\u10E0\u10D0\u10E4\u10D0\u10D3 \u10EC\u10D0\u10EE\u10D5\u10D8\u10D3\u10D4, \u10DB\u10D0\u10E0\u10E2\u10DD \u10EC\u10D0\u10D3\u10D8; \u10D7\u10E3 \u10D2\u10D8\u10DC\u10D3\u10D0 \u10E8\u10DD\u10E0\u10E1 \u10EC\u10D0\u10EE\u10D5\u10D8\u10D3\u10D4, \u10D4\u10E0\u10D7\u10D0\u10D3 \u10D8\u10D0\u10E0\u10D4.\u201C \u2014 \u10D0\u10E4\u10E0\u10D8\u10D9\u10E3\u10DA\u10D8 \u10D0\u10DC\u10D3\u10D0\u10D6\u10D0",
